import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export const DEFAULT_DATA_PATH = path.resolve(process.cwd(), 'data', 'books.json');

export class BookStore {
  constructor(filePath = process.env.BOOKS_FILE || DEFAULT_DATA_PATH) {
    this.filePath = path.resolve(filePath);
    this._ensureFile();
  }

  _ensureFile() {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    if (!fs.existsSync(this.filePath)) {
      fs.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  _readAll() {
    this._ensureFile();
    try {
      const raw = fs.readFileSync(this.filePath, 'utf8').trim();
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed;
      if (parsed && Array.isArray(parsed.books)) return parsed.books;
      return [];
    } catch {
      return [];
    }
  }

  _writeAll(books) {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const tmpPath = `${this.filePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(tmpPath, JSON.stringify(books, null, 2), 'utf8');
    fs.renameSync(tmpPath, this.filePath);
  }

  getAll() {
    return this._readAll();
  }

  getById(id) {
    const books = this._readAll();
    return books.find((b) => String(b.id) === String(id)) || null;
  }

  add({ title, author, notes = '', status = 'reading' }) {
    const cleanTitle = String(title ?? '').trim();
    const cleanAuthor = String(author ?? '').trim();
    const cleanNotes = String(notes ?? '').trim();

    if (!cleanTitle) {
      throw new Error('Title is required');
    }
    if (!cleanAuthor) {
      throw new Error('Author is required');
    }

    const normalizedStatus =
      status === 'finished' || status === true ? 'finished' : 'reading';

    const now = new Date().toISOString();
    const book = {
      id: crypto.randomUUID(),
      title: cleanTitle,
      author: cleanAuthor,
      notes: cleanNotes,
      status: normalizedStatus,
      finished: normalizedStatus === 'finished',
      createdAt: now,
      finishedAt: normalizedStatus === 'finished' ? now : null,
    };

    const books = this._readAll();
    books.push(book);
    this._writeAll(books);
    return book;
  }

  update(id, updates = {}) {
    const books = this._readAll();
    const index = books.findIndex((b) => String(b.id) === String(id));
    if (index === -1) return null;

    const existing = books[index];
    const updated = { ...existing };

    if (updates.title !== undefined) {
      const cleanTitle = String(updates.title).trim();
      if (!cleanTitle) throw new Error('Title cannot be empty');
      updated.title = cleanTitle;
    }

    if (updates.author !== undefined) {
      const cleanAuthor = String(updates.author).trim();
      if (!cleanAuthor) throw new Error('Author cannot be empty');
      updated.author = cleanAuthor;
    }

    if (updates.notes !== undefined) {
      updated.notes = String(updates.notes).trim();
    }

    if (updates.status !== undefined || updates.finished !== undefined) {
      const isFinished =
        updates.status === 'finished' ||
        updates.finished === true ||
        updates.finished === 'true';
      updated.status = isFinished ? 'finished' : 'reading';
      updated.finished = isFinished;
      updated.finishedAt = isFinished
        ? existing.finishedAt || new Date().toISOString()
        : null;
    }

    books[index] = updated;
    this._writeAll(books);
    return updated;
  }

  markFinished(id) {
    return this.update(id, { status: 'finished', finished: true });
  }

  remove(id) {
    const books = this._readAll();
    const index = books.findIndex((b) => String(b.id) === String(id));
    if (index === -1) return false;
    books.splice(index, 1);
    this._writeAll(books);
    return true;
  }
}

