import http from 'node:http';
import { URL } from 'node:url';
import { BookStore } from './store.js';

export function escapeHtml(str = '') {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderLayout(title, bodyContent) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${escapeHtml(title)} — Reading Tracker</title>
  <style>
    :root {
      --bg: #faf9f6;
      --surface: #ffffff;
      --border: #e5e3dc;
      --text: #1c1b18;
      --muted: #6b6860;
      --accent: #2c5e43;
      --accent-hover: #214732;
      --badge-reading-bg: #eef6f0;
      --badge-reading-text: #2c5e43;
      --badge-finished-bg: #f0efe9;
      --badge-finished-text: #55524a;
      --danger: #b33939;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      padding: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Georgia, sans-serif;
      background-color: var(--bg);
      color: var(--text);
      line-height: 1.5;
    }
    header {
      border-bottom: 1px solid var(--border);
      background: var(--surface);
      padding: 1rem 1.5rem;
    }
    .container {
      max-width: 820px;
      margin: 0 auto;
      padding: 1.5rem;
    }
    header .nav-container {
      max-width: 820px;
      margin: 0 auto;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    header a.brand {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--text);
      text-decoration: none;
      letter-spacing: -0.02em;
    }
    h1, h2, h3 {
      margin-top: 0;
      letter-spacing: -0.01em;
    }
    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1.25rem;
      margin-bottom: 1.25rem;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    }
    .form-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.75rem;
    }
    @media (max-width: 600px) {
      .form-grid { grid-template-columns: 1fr; }
    }
    .form-group {
      margin-bottom: 0.75rem;
    }
    label {
      display: block;
      font-size: 0.875rem;
      font-weight: 600;
      margin-bottom: 0.25rem;
      color: var(--text);
    }
    input[type="text"], textarea, select {
      width: 100%;
      padding: 0.55rem 0.75rem;
      border: 1px solid var(--border);
      border-radius: 6px;
      font-size: 0.95rem;
      font-family: inherit;
      background: #fff;
      color: var(--text);
    }
    textarea {
      min-height: 80px;
      resize: vertical;
    }
    button, .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 0.5rem 0.95rem;
      border-radius: 6px;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      border: 1px solid transparent;
      text-decoration: none;
      transition: background 0.15s ease;
    }
    .btn-primary {
      background: var(--accent);
      color: #fff;
    }
    .btn-primary:hover {
      background: var(--accent-hover);
    }
    .btn-secondary {
      background: var(--surface);
      border-color: var(--border);
      color: var(--text);
    }
    .btn-secondary:hover {
      background: var(--bg);
    }
    .book-list {
      list-style: none;
      padding: 0;
      margin: 0;
      display: grid;
      gap: 0.75rem;
    }
    .book-item {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1rem 1.25rem;
    }
    .book-info a.book-link {
      font-size: 1.05rem;
      font-weight: 600;
      color: var(--text);
      text-decoration: none;
    }
    .book-info a.book-link:hover {
      color: var(--accent);
      text-decoration: underline;
    }
    .book-author {
      color: var(--muted);
      font-size: 0.9rem;
      margin-top: 0.15rem;
    }
    .book-notes-preview {
      color: var(--muted);
      font-size: 0.85rem;
      margin-top: 0.35rem;
    }
    .badge {
      display: inline-block;
      padding: 0.2rem 0.55rem;
      border-radius: 999px;
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.03em;
    }
    .badge-reading {
      background: var(--badge-reading-bg);
      color: var(--badge-reading-text);
    }
    .badge-finished {
      background: var(--badge-finished-bg);
      color: var(--badge-finished-text);
    }
    .empty-state {
      color: var(--muted);
      font-style: italic;
      padding: 1rem 0;
    }
    .section-header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin: 1.75rem 0 0.75rem;
      border-bottom: 1px solid var(--border);
      padding-bottom: 0.4rem;
    }
    .share-box {
      display: flex;
      gap: 0.5rem;
      align-items: center;
      margin-top: 0.75rem;
    }
    .share-box input {
      background: var(--bg);
      font-family: monospace;
      font-size: 0.85rem;
    }
    .notes-content {
      white-space: pre-wrap;
      background: var(--bg);
      padding: 1rem;
      border-radius: 6px;
      border: 1px solid var(--border);
      margin-top: 0.5rem;
    }
    .actions-row {
      display: flex;
      gap: 0.5rem;
      align-items: center;
      flex-wrap: wrap;
    }
  </style>
</head>
<body>
  <header>
    <div class="nav-container">
      <a href="/" class="brand">My Reading List</a>
      <a href="/" class="btn btn-secondary">All Books</a>
    </div>
  </header>
  <main class="container">
    ${bodyContent}
  </main>
</body>
</html>`;
}

function renderHomePage(books, errorMsg = '') {
  const readingBooks = books.filter((b) => b.status !== 'finished' && !b.finished);
  const finishedBooks = books.filter((b) => b.status === 'finished' || b.finished);

  const renderBookItem = (book) => {
    const isFinished = book.status === 'finished' || book.finished;
    return `<li class="book-item" data-book-id="${escapeHtml(book.id)}">
      <div class="book-info">
        <a class="book-link" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <div class="book-author">by ${escapeHtml(book.author)}</div>
        ${book.notes ? `<div class="book-notes-preview">${escapeHtml(book.notes)}</div>` : ''}
      </div>
      <div class="actions-row">
        <a class="btn btn-secondary" href="/books/${encodeURIComponent(book.id)}">View</a>
        ${
          !isFinished
            ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="margin:0;">
                <button type="submit" class="btn btn-primary">Mark as Finished</button>
              </form>`
            : `<span class="badge badge-finished">Finished</span>`
        }
      </div>
    </li>`;
  };

  return renderLayout(
    'Books',
    `
    ${errorMsg ? `<div class="card" style="border-color: var(--danger); color: var(--danger);">${escapeHtml(errorMsg)}</div>` : ''}
    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading">Add a Book</h2>
      <form method="POST" action="/books" id="add-book-form">
        <div class="form-grid">
          <div class="form-group">
            <label for="title">Title</label>
            <input type="text" id="title" name="title" required placeholder="e.g. The Left Hand of Darkness" />
          </div>
          <div class="form-group">
            <label for="author">Author</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Ursula K. Le Guin" />
          </div>
        </div>
        <div class="form-group">
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Thoughts, quotes, or chapter notes..."></textarea>
        </div>
        <button type="submit" class="btn btn-primary">Add Book</button>
      </form>
    </section>

    <section aria-labelledby="currently-reading-heading" id="currently-reading">
      <div class="section-header">
        <h2 id="currently-reading-heading" style="margin:0;">Currently Reading (${readingBooks.length})</h2>
      </div>
      ${
        readingBooks.length === 0
          ? `<p class="empty-state">No books currently being read.</p>`
          : `<ul class="book-list">${readingBooks.map(renderBookItem).join('\n')}</ul>`
      }
    </section>

    <section aria-labelledby="finished-books-heading" id="finished-books">
      <div class="section-header">
        <h2 id="finished-books-heading" style="margin:0;">Finished (${finishedBooks.length})</h2>
      </div>
      ${
        finishedBooks.length === 0
          ? `<p class="empty-state">No finished books yet.</p>`
          : `<ul class="book-list">${finishedBooks.map(renderBookItem).join('\n')}</ul>`
      }
    </section>
  `
  );
}

function renderBookDetailPage(book, hostUrl) {
  const isFinished = book.status === 'finished' || book.finished;
  const sharePath = `/books/${encodeURIComponent(book.id)}`;
  const fullShareUrl = hostUrl ? `${hostUrl}${sharePath}` : sharePath;

  return renderLayout(
    book.title,
    `
    <div style="margin-bottom: 1rem;">
      <a href="/" class="btn btn-secondary">&larr; Back to all books</a>
    </div>

    <article class="card" data-book-id="${escapeHtml(book.id)}">
      <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:1rem; flex-wrap:wrap;">
        <div>
          <h1 class="book-title" style="margin-bottom: 0.25rem;">${escapeHtml(book.title)}</h1>
          <p class="book-author" style="font-size: 1.1rem; margin-top: 0;">by <span class="author-name">${escapeHtml(book.author)}</span></p>
        </div>
        <div>
          <span class="badge ${isFinished ? 'badge-finished' : 'badge-reading'}">
            ${isFinished ? 'Finished' : 'Currently Reading'}
          </span>
        </div>
      </div>

      <div style="margin-top: 1.25rem;">
        <h3>My Notes</h3>
        ${
          book.notes
            ? `<div class="notes-content" id="book-notes">${escapeHtml(book.notes)}</div>`
            : `<p class="empty-state" id="book-notes">No notes added yet.</p>`
        }
      </div>

      <div class="actions-row" style="margin-top: 1.25rem;">
        ${
          !isFinished
            ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="margin:0;">
                <button type="submit" class="btn btn-primary">Mark as Finished</button>
              </form>`
            : ''
        }
      </div>

      <hr style="border:0; border-top:1px solid var(--border); margin: 1.5rem 0;" />

      <section aria-labelledby="update-notes-heading">
        <h3 id="update-notes-heading">Update Notes</h3>
        <form method="POST" action="/books/${encodeURIComponent(book.id)}/notes">
          <div class="form-group">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes">${escapeHtml(book.notes || '')}</textarea>
          </div>
          <button type="submit" class="btn btn-secondary">Save Notes</button>
        </form>
      </section>

      <hr style="border:0; border-top:1px solid var(--border); margin: 1.5rem 0;" />

      <section aria-labelledby="share-book-heading">
        <h3 id="share-book-heading" style="margin-bottom: 0.25rem;">Share this book</h3>
        <p style="margin: 0; font-size: 0.875rem; color: var(--muted);">Send this direct link to share this book:</p>
        <div class="share-box">
          <input type="text" id="share-link" readonly value="${escapeHtml(fullShareUrl)}" aria-label="Shareable link" />
          <a href="${escapeHtml(sharePath)}" class="btn btn-secondary">Direct Link</a>
          <button type="button" class="btn btn-secondary" onclick="navigator.clipboard && navigator.clipboard.writeText(document.getElementById('share-link').value)">Copy Link</button>
        </div>
      </section>
    </article>
  `
  );
}

function renderNotFoundPage(message = 'Book not found.') {
  return renderLayout(
    'Not Found',
    `
    <div class="card">
      <h1>404 — Not Found</h1>
      <p>${escapeHtml(message)}</p>
      <a href="/" class="btn btn-primary">Back to Reading List</a>
    </div>
  `
  );
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk.toString('utf8');
      if (raw.length > 1e6) {
        reject(new Error('Payload too large'));
        req.destroy();
      }
    });
    req.on('end', () => {
      const contentType = (req.headers['content-type'] || '').split(';')[0].trim();
      if (!raw) {
        resolve({});
        return;
      }
      if (contentType === 'application/json') {
        try {
          resolve(JSON.parse(raw));
        } catch (err) {
          reject(new Error('Invalid JSON'));
        }
        return;
      }
      if (contentType === 'application/x-www-form-urlencoded') {
        const params = new URLSearchParams(raw);
        const obj = {};
        for (const [k, v] of params.entries()) {
          obj[k] = v;
        }
        resolve(obj);
        return;
      }
      // Try JSON first, then URLSearchParams fallback
      try {
        resolve(JSON.parse(raw));
      } catch {
        const params = new URLSearchParams(raw);
        const obj = {};
        for (const [k, v] of params.entries()) {
          obj[k] = v;
        }
        resolve(obj);
      }
    });
    req.on('error', reject);
  });
}

function wantsJson(req, pathname) {
  if (pathname.startsWith('/api/')) return true;
  const accept = req.headers['accept'] || '';
  const contentType = req.headers['content-type'] || '';
  if (accept.includes('application/json') && !accept.includes('text/html')) {
    return true;
  }
  if (contentType.includes('application/json') && !accept.includes('text/html')) {
    return true;
  }
  return false;
}

function sendJson(res, status, data) {
  const payload = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createApp({ dataFile } = {}) {
  const store = new BookStore(dataFile);

  const handler = async (req, res) => {
    try {
      const host = req.headers.host || 'localhost';
      const protocol = req.headers['x-forwarded-proto'] || 'http';
      const baseUrl = `${protocol}://${host}`;
      const url = new URL(req.url || '/', baseUrl);
      const pathname = url.pathname.replace(/\/+$/, '') || '/';
      const method = (req.method || 'GET').toUpperCase();

      // Health check
      if (method === 'GET' && pathname === '/health') {
        return sendJson(res, 200, { status: 'ok' });
      }

      // API: GET /api/books
      if (method === 'GET' && pathname === '/api/books') {
        const books = store.getAll();
        return sendJson(res, 200, books);
      }

      // API: POST /api/books
      if (method === 'POST' && pathname === '/api/books') {
        let body;
        try {
          body = await parseBody(req);
        } catch (err) {
          return sendJson(res, 400, { error: err.message });
        }
        try {
          const book = store.add(body);
          return sendJson(res, 201, book);
        } catch (err) {
          return sendJson(res, 400, { error: err.message });
        }
      }

      // API: single book routes /api/books/:id, /api/books/:id/finish, /api/books/:id/notes
      const apiBookMatch = pathname.match(/^\/api\/books\/([^/]+)(?:\/(finish|notes))?$/);
      if (apiBookMatch) {
        const bookId = decodeURIComponent(apiBookMatch[1]);
        const subAction = apiBookMatch[2];

        if (method === 'GET' && !subAction) {
          const book = store.getById(bookId);
          if (!book) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, book);
        }

        if ((method === 'POST' || method === 'PATCH' || method === 'PUT') && subAction === 'finish') {
          const updated = store.markFinished(bookId);
          if (!updated) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, updated);
        }

        if ((method === 'POST' || method === 'PATCH' || method === 'PUT') && subAction === 'notes') {
          const body = await parseBody(req);
          const updated = store.update(bookId, { notes: body.notes ?? '' });
          if (!updated) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, updated);
        }

        if ((method === 'PATCH' || method === 'PUT') && !subAction) {
          try {
            const body = await parseBody(req);
            const updated = store.update(bookId, body);
            if (!updated) return sendJson(res, 404, { error: 'Book not found' });
            return sendJson(res, 200, updated);
          } catch (err) {
            return sendJson(res, 400, { error: err.message });
          }
        }

        if (method === 'DELETE' && !subAction) {
          const removed = store.remove(bookId);
          if (!removed) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, { deleted: true });
        }
      }

      // Web: GET / or GET /books
      if (method === 'GET' && (pathname === '/' || pathname === '/books')) {
        const books = store.getAll();
        if (wantsJson(req, pathname)) {
          return sendJson(res, 200, books);
        }
        return sendHtml(res, 200, renderHomePage(books));
      }

      // Web: POST /books (Add a book from form or JSON)
      if (method === 'POST' && (pathname === '/books' || pathname === '/')) {
        let body;
        try {
          body = await parseBody(req);
        } catch (err) {
          if (wantsJson(req, pathname)) return sendJson(res, 400, { error: err.message });
          return sendHtml(res, 400, renderHomePage(store.getAll(), err.message));
        }
        try {
          const book = store.add(body);
          if (wantsJson(req, pathname)) {
            return sendJson(res, 201, book);
          }
          return redirect(res, '/');
        } catch (err) {
          if (wantsJson(req, pathname)) {
            return sendJson(res, 400, { error: err.message });
          }
          return sendHtml(res, 400, renderHomePage(store.getAll(), err.message));
        }
      }

      // Web: Single book routes /books/:id, /books/:id/finish, /books/:id/notes, /book/:id
      const webBookMatch = pathname.match(/^\/books?\/([^/]+)(?:\/(finish|notes|delete))?$/);
      if (webBookMatch) {
        const bookId = decodeURIComponent(webBookMatch[1]);
        const subAction = webBookMatch[2];

        if (method === 'GET' && !subAction) {
          const book = store.getById(bookId);
          if (!book) {
            if (wantsJson(req, pathname)) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) return sendJson(res, 200, book);
          return sendHtml(res, 200, renderBookDetailPage(book, baseUrl));
        }

        if ((method === 'POST' || method === 'PATCH' || method === 'PUT') && subAction === 'finish') {
          const updated = store.markFinished(bookId);
          if (!updated) {
            if (wantsJson(req, pathname)) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) return sendJson(res, 200, updated);
          const referer = req.headers.referer || '';
          if (referer.includes(`/books/${encodeURIComponent(bookId)}`)) {
            return redirect(res, `/books/${encodeURIComponent(bookId)}`);
          }
          return redirect(res, '/');
        }

        if ((method === 'POST' || method === 'PATCH' || method === 'PUT') && subAction === 'notes') {
          const body = await parseBody(req);
          const updated = store.update(bookId, { notes: body.notes ?? '' });
          if (!updated) {
            if (wantsJson(req, pathname)) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) return sendJson(res, 200, updated);
          return redirect(res, `/books/${encodeURIComponent(bookId)}`);
        }

        if ((method === 'POST' || method === 'PATCH' || method === 'PUT') && !subAction) {
          const body = await parseBody(req);
          const updated = store.update(bookId, body);
          if (!updated) {
            if (wantsJson(req, pathname)) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) return sendJson(res, 200, updated);
          return redirect(res, `/books/${encodeURIComponent(bookId)}`);
        }

        if ((method === 'DELETE' || (method === 'POST' && subAction === 'delete'))) {
          const removed = store.remove(bookId);
          if (!removed) {
            if (wantsJson(req, pathname)) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) return sendJson(res, 200, { deleted: true });
          return redirect(res, '/');
        }
      }

      if (wantsJson(req, pathname)) {
        return sendJson(res, 404, { error: 'Not Found' });
      }
      return sendHtml(res, 404, renderNotFoundPage('Page not found.'));
    } catch (err) {
      if (wantsJson(req, req.url || '')) {
        return sendJson(res, 500, { error: err.message || 'Internal Server Error' });
      }
      return sendHtml(res, 500, renderNotFoundPage('Something went wrong.'));
    }
  };

  const server = http.createServer(handler);
  return { server, store, handler };
}

