      color: var(--text);
    }
    input[type="text"], textarea, select {
      width: 100%;
      padding: 0.55rem 0.75rem;
      border: 1px solid var(--border);
      border-radius: 6px;
      font-size: 0.95rem;
      font-family: inherit;
      background: #fff;
      color: var(--text);
    }
    textarea {
      min-height: 80px;
      resize: vertical;
    }
