      font-size: 0.85rem;
    }
    .notes-content {
      white-space: pre-wrap;
      background: var(--bg);
      padding: 1rem;
      border-radius: 6px;
      border: 1px solid var(--border);
      margin-top: 0.5rem;
    }
    .actions-row {
      display: flex;
      gap: 0.5rem;
      align-items: center;
      flex-wrap: wrap;
    }
  </style>
</head>
<body>
  <header>
    <div class="nav-container">
      <a href="/" class="brand">My Reading List</a>
      <a href="/" class="btn btn-secondary">All Books</a>
    </div>
  </header>
  <main class="container">
    ${bodyContent}
  </main>
</body>
</html>`;
}

function renderHomePage(books, errorMsg = '') {
  const readingBooks = books.filter((b) => b.status !== 'finished' && !b.finished);
  const finishedBooks = books.filter((b) => b.status === 'finished' || b.finished);

  const renderBookItem = (book) => {
    const isFinished = book.status === 'finished' || book.finished;
    return `<li class="book-item" data-book-id="${escapeHtml(book.id)}">
      <div class="book-info">
        <a class="book-link" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <div class="book-author">by ${escapeHtml(book.author)}</div>
        ${book.notes ? `<div class="book-notes-preview">${escapeHtml(book.notes)}</div>` : ''}
      </div>
      <div class="actions-row">
        <a class="btn btn-secondary" href="/books/${encodeURIComponent(book.id)}">View</a>
        ${
          !isFinished
            ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="margin:0;">
