import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createApp } from '../src/server.js';
import { BookStore } from '../src/store.js';

function startTestServer(dataFile) {
  return new Promise((resolve, reject) => {
    const app = createApp({ dataFile });
    app.server.listen(0, '127.0.0.1', () => {
      const addr = app.server.address();
      const baseUrl = `http://127.0.0.1:${addr.port}`;
      resolve({
        ...app,
        baseUrl,
        close: () =>
          new Promise((resClose) => {
            app.server.close(() => resClose());
          }),
      });
    });
    app.server.on('error', reject);
  });
}

describe('Reading Tracker App', () => {
  let tmpDir;
  let dataFile;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'reading-tracker-test-'));
    dataFile = path.join(tmpDir, 'books.json');
  });

  afterEach(() => {
    if (tmpDir && fs.existsSync(tmpDir)) {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it('shows currently reading and finished sections on the home page', async () => {
    const srv = await startTestServer(dataFile);
    try {
      const res = await fetch(`${srv.baseUrl}/`);
      expect(res.status).toBe(200);
      const html = await res.text();
      expect(html).toContain('Currently Reading');
      expect(html).toContain('Finished');
      expect(html).toContain('<form method="POST" action="/books"');
    } finally {
      await srv.close();
    }
  });

  it('adds a book via form submission, displays it under Currently Reading, and links to its detail page', async () => {
    const srv = await startTestServer(dataFile);
    try {
      const formBody = new URLSearchParams({
        title: 'Dune',
        author: 'Frank Herbert',
        notes: 'Fear is the mind-killer.',
      });

      const postRes = await fetch(`${srv.baseUrl}/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formBody.toString(),
        redirect: 'manual',
      });
      expect(postRes.status).toBe(303);

      const homeRes = await fetch(`${srv.baseUrl}/`);
      const homeHtml = await homeRes.text();
      expect(homeHtml).toContain('Dune');
      expect(homeHtml).toContain('Frank Herbert');
      expect(homeHtml).toContain('Currently Reading (1)');
      expect(homeHtml).toContain('Finished (0)');

      const books = srv.store.getAll();
      expect(books).toHaveLength(1);
      const bookId = books[0].id;
      expect(homeHtml).toContain(`/books/${bookId}`);
    } finally {
      await srv.close();
    }
  });

  it('marks a book as finished and moves it to the Finished list', async () => {
    const srv = await startTestServer(dataFile);
    try {
      const book = srv.store.add({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Amaze! Amaze!',
      });

      const finishRes = await fetch(`${srv.baseUrl}/books/${book.id}/finish`, {
        method: 'POST',
        redirect: 'manual',
      });
      expect(finishRes.status).toBe(303);

      const homeRes = await fetch(`${srv.baseUrl}/`);
      const homeHtml = await homeRes.text();
      expect(homeHtml).toContain('Currently Reading (0)');
      expect(homeHtml).toContain('Finished (1)');
      expect(homeHtml).toContain('Project Hail Mary');

      const updated = srv.store.getById(book.id);
      expect(updated.status).toBe('finished');
      expect(updated.finished).toBe(true);
    } finally {
      await srv.close();
    }
  });

  it('serves a shareable single-book link showing title, author, and notes, and allows updating notes', async () => {
    const srv = await startTestServer(dataFile);
    try {
      const book = srv.store.add({
        title: 'Piranesi',
        author: 'Susanna Clarke',
        notes: 'The Beauty of the House is immeasurable.',
      });

      const detailUrl = `${srv.baseUrl}/books/${book.id}`;
      const detailRes = await fetch(detailUrl);
      expect(detailRes.status).toBe(200);
      const detailHtml = await detailRes.text();

      expect(detailHtml).toContain('Piranesi');
      expect(detailHtml).toContain('Susanna Clarke');
      expect(detailHtml).toContain('The Beauty of the House is immeasurable.');
      expect(detailHtml).toContain(`/books/${book.id}`);

      // Update notes on single book page
      const notesForm = new URLSearchParams({
        notes: 'Updated notes after finishing chapter 3.',
      });
      const updateRes = await fetch(`${srv.baseUrl}/books/${book.id}/notes`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: notesForm.toString(),
        redirect: 'manual',
      });
      expect(updateRes.status).toBe(303);

      const detailResAfter = await fetch(detailUrl);
      const detailHtmlAfter = await detailResAfter.text();
      expect(detailHtmlAfter).toContain('Updated notes after finishing chapter 3.');
    } finally {
      await srv.close();
    }
  });

  it('persists books to a JSON file on disk so they remain after server restart', async () => {
    // First server instance
    const srv1 = await startTestServer(dataFile);
    let createdBookId;
    try {
      const apiRes = await fetch(`${srv1.baseUrl}/api/books`, {
        method: 'POST',
